#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

int main(int argc, char **argv)
{
	char *buf;
	int fd;
	int i;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	buf = malloc(1024);
	if (!buf) {
		perror("malloc");
		exit(1);
	}

	ret = read(fd, buf, 1024);
	if (ret < 0) {
		perror("read");
		exit(1);
	}

	for (i = 0; i < ret; i++) {
		if (buf[i] == '\n') {
			buf[i] = '\0';
			printf("%s\n", buf);
			buf = malloc(1024);
			if (!buf) {
				perror("malloc");
				exit(1);
			}
		}
	}

	free(buf);
	close(fd);

	return 0;
}
