static ssize_t add_slot_store(struct kobject *kobj, struct kobj_attribute *attr,
			      const char *buf, size_t nbytes)
{
	char drc_name[MAX_DRC_NAME_LEN];
	char *end;
	int rc;

	if (nbytes >= MAX_DRC_NAME_LEN)
		return 0;

	memcpy(drc_name, buf, nbytes);

	end = strchr(drc_name, '\n');
	if (!end)
		end = &drc_name[nbytes];
	*end = '\0';

	rc = dlpar_add_slot(drc_name);
	if (rc)
		return rc;

	return nbytes;
}

int main(int argc, char **argv)
{
	int fd;
	char buf[MAX_DRC_NAME_LEN];
	ssize_t nbytes;

	fd = open("/sys/kernel/config/drc/add_slot", O_WRONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	nbytes = read(0, buf, MAX_DRC_NAME_LEN);
	if (nbytes < 0) {
		perror("read");
		exit(1);
	}

	nbytes = write(fd, buf, nbytes);
	if (nbytes < 0) {
		perror("write");
		exit(1);
	}

	close(fd);

	return 0;
}
