#define PAGE_SIZE 4096

int main(int argc, char *argv[])
{
	int fd;
	void *addr;
	int i;
	int sum = 0;
	int *p;

	fd = open("consolemap.c", O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	addr = mmap(NULL, PAGE_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	p = (int *)addr;
	for (i = 0; i < PAGE_SIZE/4; i++) {
		sum += p[i];
	}

	printf("sum = %d\n", sum);

	munmap(addr, PAGE_SIZE);
	close(fd);

	return 0;
}
