{
	char buf[100];
	int max;
	int err = -EINVAL;
	size_t size;
	int *vclock_index;

	if (argc!= 2) {
		printf("Usage: %s <max>\n", argv[0]);
		return 1;
	}

	max = atoi(argv[1]);
	if (max == 0)
		return 0;

	if (max < 0)
		return -EINVAL;

	if (max == 1)
		return 0;

	size = sizeof(int) * max;
	vclock_index = malloc(size);
	if (!vclock_index) {
		err = -ENOMEM;
		goto out;
	}

	size = sizeof(int) * 1;
	memcpy(vclock_index, &max, size);

	free(vclock_index);
	return 0;
out:
	free(vclock_index);
	return err;
}
