#define KERN_INFO "software IO TLB [mem %#010llx-%#010llx] (%luMB) mapped at [%p-%p]\n"

int main(int argc, char *argv[])
{
	unsigned long bytes = IO_TLB_NSLABS << IO_TLB_SHIFT;
	unsigned char *vstart, *vend;

	if (NO_IOTLB_MEMORY) {
		printf("software IO TLB: No low mem\n");
		return 0;
	}

	vstart = (unsigned char *)IO_TLB_START;
	vend = (unsigned char *)IO_TLB_END;

	printf(KERN_INFO, (unsigned long long)IO_TLB_START, (unsigned long long)IO_TLB_END, bytes >> 20, vstart, vend - 1);

	return 0;
}
