#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <errno.h>

#define BUF_SIZE 1024

int main(int argc, char *argv[])
{
	int fd;
	char *buf;
	int ret;
	pid_t pid;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return -1;
	}

	fd = open(argv[1], O_RDWR);
	if (fd < 0) {
		printf("open %s failed: %s\n", argv[1], strerror(errno));
		return -1;
	}

	buf = mmap(NULL, BUF_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (buf == MAP_FAILED) {
		printf("mmap failed: %s\n", strerror(errno));
		return -1;
	}

	pid = fork();
	if (pid < 0) {
		printf("fork failed: %s\n", strerror(errno));
		return -1;
	} else if (pid == 0) {
		/* child process */
		printf("child process\n");
		ret = check_stack_guard_page(buf, 0);
		if (ret < 0) {
			printf("check_stack_guard_page failed: %s\n", strerror(-ret));
			return -1;
		}
		printf("check_stack_guard_page success\n");
		return 0;
	} else {
		/* parent process */
		printf("parent process\n");
		wait(NULL);
		return 0;
	}
}
