	buf = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		return -1;
	}

	for (i = 0; i < PAGE_SIZE; i++) {
		buf[i] = 0;
	}

	ret = munmap(buf, PAGE_SIZE);
	if (ret < 0) {
		perror("munmap");
		return -1;
	}

	ret = close(fd);
	if (ret < 0) {
		perror("close");
		return -1;
	}

	return 0;
}
