#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>

#define PAGE_SIZE 4096

int main(int argc, char *argv[])
{
	int fd;
	void *ptr;
	int i;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return -1;
	}

	fd = open(argv[1], O_RDWR);
	if (fd < 0) {
		printf("Error opening file %s\n", argv[1]);
		return -1;
	}

	ptr = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (ptr == MAP_FAILED) {
		printf("Error mapping file %s\n", argv[1]);
		return -1;
	}

	for (i = 0; i < PAGE_SIZE; i++) {
		if (i < 256) {
			if (((char *)ptr)[i]!= 0) {
				printf("Not vulnerable\n");
				return 0;
			}
		} else {
			if (((char *)ptr)[i]!= 0) {
				printf("Vulnerable\n");
				return 1;
			}
		}
	}

	printf("Not sure\n");
	return 2;
}
