#include <errno.h>

#define PAGE_SIZE 4096

int main(int argc, char *argv[])
{
	int fd;
	void *addr;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(EXIT_FAILURE);
	}

	fd = open(argv[1], O_RDWR);
	if (fd == -1) {
		perror("open");
		exit(EXIT_FAILURE);
	}

	addr = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(EXIT_FAILURE);
	}

	ret = __copy_to_user_inatomic(addr, addr, PAGE_SIZE);
	if (ret) {
		printf("1\n");
		exit(EXIT_SUCCESS);
	}

	munmap(addr, PAGE_SIZE);
	close(fd);

	printf("0\n");
	exit(EXIT_SUCCESS);
}
