#include <errno.h>

#define BUF_SIZE 1024

int main(int argc, char *argv[])
{
	int fd;
	char *buf;
	int ret;
	int i;
	int status;
	pid_t pid;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDWR);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	buf = mmap(NULL, BUF_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	pid = fork();
	if (pid < 0) {
		perror("fork");
		exit(1);
	}

	if (pid == 0) {
		for (i = 0; i < 1000000; i++) {
			ret = write(fd, buf, BUF_SIZE);
			if (ret < 0) {
				perror("write");
				exit(1);
			}
		}

		exit(0);
	}

	wait(&status);

	munmap(buf, BUF_SIZE);
	close(fd);

	return 0;
}
