#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>

#define MAX_SIZE 1024

int main(int argc, char *argv[])
{
	int fd;
	char *buf;
	int i;
	int len;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	buf = mmap(NULL, MAX_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	len = strlen(buf);
	for (i = 0; i < len; i++) {
		if (buf[i] == '\n') {
			buf[i] = '\0';
			break;
		}
	}

	ret = strcmp(buf, "1");
	if (ret == 0) {
		printf("1\n");
	} else if (ret == 1) {
		printf("0\n");
	} else {
		printf("not sure\n");
	}

	munmap(buf, MAX_SIZE);
	close(fd);

	return 0;
}
