#include <sys/mman.h>

#define PAGE_SIZE 4096

int main(int argc, char *argv[])
{
	int fd;
	char *buf;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return -1;
	}

	fd = open(argv[1], O_RDWR | O_CREAT, 0644);
	if (fd < 0) {
		printf("open %s failed: %s\n", argv[1], strerror(errno));
		return -1;
	}

	buf = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (buf == MAP_FAILED) {
		printf("mmap failed: %s\n", strerror(errno));
		close(fd);
		return -1;
	}

	ret = fallocate(fd, 0, 0, 0);
	if (ret < 0) {
		printf("fallocate failed: %s\n", strerror(errno));
		munmap(buf, PAGE_SIZE);
		close(fd);
		return -1;
	}

	ret = msync(buf, PAGE_SIZE, MS_SYNC);
	if (ret < 0) {
		printf("msync failed: %s\n", strerror(errno));
		munmap(buf, PAGE_SIZE);
		close(fd);
		return -1;
	}

	munmap(buf, PAGE_SIZE);
	close(fd);

	return 0;
}
