int main(int argc, char *argv[])
{
	char *buf;
	size_t count;
	int err;
	unsigned int *vclock_index;
	int max;

	if (argc!= 2) {
		printf("Usage: %s <max>\n", argv[0]);
		exit(EXIT_FAILURE);
	}

	max = atoi(argv[1]);
	if (max == 0) {
		printf("Usage: %s <max>\n", argv[0]);
		exit(EXIT_FAILURE);
	}

	buf = malloc(sizeof(char) * 10);
	if (!buf) {
		printf("malloc failed\n");
		exit(EXIT_FAILURE);
	}

	count = 10;
	err = -EINVAL;
	if (kstrtou32(buf, 0, &max) || max == 0)
		goto out;

	if (max == 0)
		goto out;

	vclock_index = kcalloc(max, sizeof(int), GFP_KERNEL);
	if (!vclock_index) {
		err = -ENOMEM;
		goto out;
	}

	free(buf);
	free(vclock_index);

	printf("1\n");
	exit(EXIT_SUCCESS);
out:
	free(buf);
	free(vclock_index);
	printf("0\n");
	exit(EXIT_FAILURE);
}
