#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <errno.h>

#define BUF_SIZE 1024

int main(int argc, char *argv[])
{
	char buf[BUF_SIZE];
	int fd;
	int ret;
	int status;
	pid_t pid;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(EXIT_FAILURE);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd == -1) {
		perror("open");
		exit(EXIT_FAILURE);
	}

	pid = fork();
	if (pid == -1) {
		perror("fork");
		exit(EXIT_FAILURE);
	}

	if (pid == 0) {
		ret = read(fd, buf, BUF_SIZE);
		if (ret == -1) {
			perror("read");
			exit(EXIT_FAILURE);
		}
		printf("%s", buf);
		exit(EXIT_SUCCESS);
	}

	waitpid(pid, &status, 0);
	if (WIFEXITED(status)) {
		if (WEXITSTATUS(status) == EXIT_SUCCESS)
			printf("1\n");
		else
			printf("0\n");
	} else {
		printf("not sure\n");
	}

	return 0;
}
