// File path: drivers/i3c/master/dw-i3c-master.c
static int dw_i3c_master_xfer(struct i3c_master_controller *master,
			      struct i3c_msg *msg,
			      struct i3c_msg *reply,
			      unsigned int nmsgs,
			      unsigned int timeout)
{
	struct dw_i3c_master *i3c = to_dw_i3c_master(master);
	struct dw_i3c_xfer *xfer;
	int ret;

	xfer = kzalloc(sizeof(*xfer) + nmsgs * sizeof(xfer->cmds[0]),
		       GFP_KERNEL);
	if (!xfer)
		return -ENOMEM;

	xfer->ncmds = nmsgs;
	list_add_tail(&xfer->node, &i3c->xfer_list);

	ret = dw_i3c_master_send_msgs(master, xfer->cmds, nmsgs, timeout);
	if (ret)
		goto out;

	ret = wait_for_completion_timeout(&xfer->comp, msecs_to_jiffies(timeout));
	if (!ret) {
		dev_err(&master->dev, "timeout\n");
		ret = -ETIMEDOUT;
		goto out;
	}

	if (xfer->ret) {
		dev_err(&master->dev, "error %d\n", xfer->ret);
		ret = xfer->ret;
		goto out;
	}

	if (reply)
		memcpy(reply, xfer->cmds, nmsgs * sizeof(struct i3c_msg));

out:
	list_del(&xfer->node);
	kfree(xfer);

	return ret;
}
