int main(int argc, char *argv[])
{
	char *filename = "test.txt";
	char *content = "This is a test file";
	int fd;

	fd = open(filename, O_CREAT | O_RDWR, 0644);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	if (write(fd, content, strlen(content)) < 0) {
		perror("write");
