#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/btrfs.h>

int main(int argc, char *argv[])
{
    int fd;
    struct btrfs_ioctl_set_reloc_profile profile;
    char *buf = NULL;

    fd = open("/dev/btrfs", O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    buf = malloc(0x1000);
    if (!buf) {
        perror("malloc");
        exit(1);
    }

    memset(&profile, 0, sizeof(profile));
    profile.profile_name = buf;
