#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdbool.h>

#define MAX_SIZE 1000000

int main(int argc, char *argv[])
{
    char *cwe_list[5];
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    int i = 0;
    int fd;

    if (argc!= 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    fd = open(argv[1], O_RDONLY);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    while ((read = getline(&line, &len, fd))!= -1) {
        if (i == 5) {
            printf("Too many CWEs\n");
            exit(EXIT_FAILURE);
        }
        if (strncmp(line, "CWE-", 4) == 0) {
            cwe_list[i] = malloc(strlen(line));
            strcpy(cwe_list[i], line);
            i++;
        }
    }

    printf("[");
    for (i = 0; i < 5; i++) {
        if (i!= 0) {
            printf(", ");
        }
        printf("\"%s\"", cwe_list[i]);
    }
    printf("]\n");

    for (i = 0; i < 5; i++) {
        free(cwe_list[i]);
    }

    if (line) {
        free(line);
    }
    close(fd);
    exit(EXIT_SUCCESS);
}
