	struct dw_i3c_master *dw_master = to_dw_i3c_master(master);
	struct dw_i3c_xfer *xfer;
	struct dw_i3c_cmd *cmds;
	int ret;

	xfer = devm_kzalloc(&master->dev, sizeof(*xfer) +
			    ncmds * sizeof(*cmds), GFP_KERNEL);
	if (!xfer)
		return -ENOMEM;

	cmds = xfer->cmds;
	for (unsigned int i = 0; i < ncmds; i++) {
		cmds[i].msg = &msg[i];
		cmds[i].reply = &reply[i];
	}

	xfer->ncmds = ncmds;
	init_completion(&xfer->comp);

	ret = dw_i3c_master_send_xfer(dw_master, xfer);
	if (ret)
		return ret;

	ret = wait_for_completion_timeout(&xfer->comp, msecs_to_jiffies(timeout));
	if (!ret) {
		dev_err(&master->dev, "transfer timed out\n");
		return -ETIMEDOUT;
	}

	return xfer->ret;
}
